def solve(g):
    if not g:
        return 0
    h, w = len(g), len(g[0])
    seen = set()
    n = 0
    for i in range(h):
        for j in range(w):
            if g[i][j] == 1 and (i, j) not in seen:
                n += 1
                st = [(i, j)]
                seen.add((i, j))
                while st:
                    a, b = st.pop()
                    for c, d in ((a + 1, b), (a - 1, b), (a, b + 1), (a, b - 1)):
