        return 1
    n = len(matrix)
    # Verify square (allow rows of length zero already handled)
    for row in matrix:
        if len(row) != n:
            # Non-square matrix: undefined, return 0 as a safe fallback
            return 0
    from fractions import Fraction
    a = [[Fraction(val) for val in row] for row in matrix]
    det = Fraction(1)
    sign = 1
    for i in range(n):
        # Find pivot row
        pivot_row = None
        for r in range(i, n):
            if a[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
