def solve(n):
    """Return the number of prime numbers strictly less than *n*.
    Uses the Sieve of Eratosthenes; works for n up to several millions efficiently.
    """
    if n <= 2:
        return 0
    # Create a boolean list where index i indicates primality of i.
    # Initially assume all numbers >=2 are prime.
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    import math
    limit = int(math.isqrt(n - 1))
    for p in range(2, limit + 1):
        if is_prime[p]:
            # Mark multiples of p starting from p*p.
            start = p * p
            for multiple in range(start, n, p):
                is_prime[multiple] = False
    # Count primes < n.
    return sum(is_prime)

