def solve(s: str) -> int:
    """Return length of the longest substring of s with all unique characters.
    Uses a sliding window with a dictionary storing the last index of each character.
    """
    last_idx = {}
    max_len = 0
    start = 0  # start index of current window
    for i, ch in enumerate(s):
        if ch in last_idx and last_idx[ch] >= start:
            # move start right after previous occurrence
            start = last_idx[ch] + 1
        last_idx[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

