        it = iter(s)
    except TypeError:
        return []
    result = []
    try:
        prev = next(it)
    except StopIteration:
        return []
    count = 1
    for ch in it:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
