def solve(grid):
    """Count the number of islands in a binary grid.
    An island is a group of adjacent 1s connected horizontally or vertically.
    Returns 0 for empty grid.
    """
    if not grid:
        return 0
    n = len(grid)
    m = len(grid[0]) if n else 0
    if m == 0:
        return 0
    visited = [[False] * m for _ in range(n)]
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if visited[i][j]:
                continue
            visited[i][j] = True
            for di, dj in ((1,0),(-1,0),(0,1),(0,-1)):
                ni, nj = i+di, j+dj
                if 0 <= ni < n and 0 <= nj < m and not visited[ni][nj] and grid[ni][nj] == 1:
                    stack.append((ni, nj))
    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                islands += 1
                dfs(i, j)
    return islands

