def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins of the given denominations. If impossible, return -1.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Initialize DP array with INF (greater than any possible answer)
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        best = INF
        for c in coins:
            if c <= i:
                cand = dp[i - c] + 1
                if cand < best:
                    best = cand
        dp[i] = best
    return dp[amount] if dp[amount] != INF else -1

