def solve(matrix):
    """Return elements of a matrix in clockwise spiral order.
    Works for any (possibly jagged) list of lists. Empty matrix returns [].
    """
    # Make a deep copy of rows to avoid mutating input
    m = [list(row) for row in matrix]
    result = []
    while m:
        # Top row
        result.extend(m.pop(0))
        if not m:
            break
        # Right column
        for row in m:
            if row:
                result.append(row.pop())
        # Bottom row (if any)
        if m:
            bottom = m.pop()
            result.extend(reversed(bottom))
        # Left column (if any)
        for row in reversed(m):
            if row:
                result.append(row.pop(0))
    return result

