def solve(nums):
    a = list(nums)
    n = len(a)
    if n <= 1:
        return a
    i = n - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i == -1:
        return sorted(a)
    j = n - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i+1:] = reversed(a[i+1:])
    return a

def reference(nums):
    import itertools
    perms = sorted(set(itertools.permutations(nums)))
    idx = perms.index(tuple(nums))
    if idx+1 < len(perms):
        return list(perms[idx+1])
    else:
        return list(perms[0])

# test many random
